#!/usr/bin/env bash
set -euo pipefail
PACKAGE_PROJECT_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
cd "${PACKAGE_PROJECT_ROOT}"


# Stage 1g: final NASDAQ test comparison between original full-model config and cumulative best.
# Selection/reporting uses 5-run Test RankIC mean; both candidates use paired seeds 20260716-20260720 and full MMR.

# final-test: original config; tower_layers=1, train_epochs=100
PYTHONPATH=src python -m satra.mmr_two_stage --is_training 1 --model_id 1g_final_5run_original_nasdaq --model model_b_spe_drt --num_runs 5 --random_seed 20260716 --data NASDAQ --market_num 20 --root_path data/processed --results results/pstr_hparam/1g_original_vs_best_5run/original --checkpoints results/pstr_hparam/1g_original_vs_best_5run/original/checkpoints --input_features all --use_grouped_inputs 0 --seq_len 16 --batch_size 1 --num_workers 0 --use_gpu 1 --pin_memory 1 --train_drop_last 1 --valid_drop_last 1 --prediction_target return --target_mode raw_return --output_activation tanh --pretrain_epochs 20 --pretrain_learning_rate 0.001 --pretrain_lr_scheduler cosine --mae_mask_ratio 0.3 --learning_rate 0.001 --train_epochs 100 --patience 20 --early_stop_metric RankIC --early_stop_mode max --lr_scheduler cosine --precision bf16_amp_tf32 --torch_compile 0 --max_grad_norm 1.0 --d_model 64 --pstr_depth 10 --pstr_kernel_size 3 --pstr_num_heads 4 --pstr_tower_layers 1 --pstr_dropout 0.1 --moe_top_k 3 --pstr_relation_path data/processed/NASDAQ_ohlcv/priors/dtw_binary_imputed_inputstandard_NASDAQ_train0-871_close_ds64_band6_cand48_top32.npz --valid_index 871 --test_index 996 --data_start_index 0

# final-test: cumulative best from 1a-1f; tower_layers=3, train_epochs=50
PYTHONPATH=src python -m satra.mmr_two_stage --is_training 1 --model_id 1g_final_5run_cumulative_best_nasdaq --model model_b_spe_drt --num_runs 5 --random_seed 20260716 --data NASDAQ --market_num 20 --root_path data/processed --results results/pstr_hparam/1g_original_vs_best_5run/cumulative_best --checkpoints results/pstr_hparam/1g_original_vs_best_5run/cumulative_best/checkpoints --input_features all --use_grouped_inputs 0 --seq_len 16 --batch_size 1 --num_workers 0 --use_gpu 1 --pin_memory 1 --train_drop_last 1 --valid_drop_last 1 --prediction_target return --target_mode raw_return --output_activation tanh --pretrain_epochs 20 --pretrain_learning_rate 0.001 --pretrain_lr_scheduler cosine --mae_mask_ratio 0.3 --learning_rate 0.001 --train_epochs 50 --patience 20 --early_stop_metric RankIC --early_stop_mode max --lr_scheduler cosine --precision bf16_amp_tf32 --torch_compile 0 --max_grad_norm 1.0 --d_model 64 --pstr_depth 10 --pstr_kernel_size 3 --pstr_num_heads 4 --pstr_tower_layers 3 --pstr_dropout 0.1 --moe_top_k 3 --pstr_relation_path data/processed/NASDAQ_ohlcv/priors/dtw_binary_imputed_inputstandard_NASDAQ_train0-871_close_ds64_band6_cand48_top32.npz --valid_index 871 --test_index 996 --data_start_index 0
